    diffuseIntensity = mapperUBO.DiffuseIntensityBF;
    specularColor = mapperUBO.SpecularColorBF;
    specularIntensity = mapperUBO.SpecularIntensityBF;
    opacity = mapperUBO.OpacityBF;
    ior = mapperUBO.BaseIORBF;
